import javax.swing.*;import javax.swing.table.*;import java.awt.*;import java.sql.*;import java.util.*;import java.util.List;import java.util.regex.*;
public class EventRegistrationApp extends JFrame{
static final String URL="jdbc:mariadb://localhost:3306/csa09_test",USER="root",PASS="change_me";
static Connection db()throws SQLException{return DriverManager.getConnection(URL,USER,PASS);}
static class Dao{List<String>events()throws SQLException{List<String>x=new ArrayList<>();try(Connection c=db();PreparedStatement p=c.prepareStatement("SELECT event_name FROM event ORDER BY event_name");ResultSet r=p.executeQuery()){while(r.next())x.add(r.getString(1));}return x;}
void insert(String ev,String reg,String name,String email)throws SQLException{String q="INSERT INTO registration(event_id,reg_no,student_name,email) SELECT event_id,?,?,? FROM event WHERE event_name=?";try(Connection c=db();PreparedStatement p=c.prepareStatement(q)){p.setString(1,reg);p.setString(2,name);p.setString(3,email);p.setString(4,ev);p.executeUpdate();}}
List<String[]>page(String ev,int off)throws SQLException{List<String[]>x=new ArrayList<>();String q="SELECT r.reg_no,r.student_name,r.email FROM registration r JOIN event e ON e.event_id=r.event_id WHERE (?='All' OR e.event_name=?) ORDER BY r.reg_id LIMIT 25 OFFSET ?";try(Connection c=db();PreparedStatement p=c.prepareStatement(q)){p.setString(1,ev);p.setString(2,ev);p.setInt(3,off);try(ResultSet r=p.executeQuery()){while(r.next())x.add(new String[]{r.getString(1),r.getString(2),r.getString(3)});}}return x;}}
static class Service{Dao d;Service(Dao d){this.d=d;}void register(String ev,String r,String n,String m)throws Exception{if(r==null||!r.matches("\\d{9}"))throw new IllegalArgumentException("Register number must be 9 digits");if(n==null||!n.trim().matches("[A-Za-z .]{2,60}"))throw new IllegalArgumentException("Invalid name");if(m==null||!Pattern.matches("[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}",m))throw new IllegalArgumentException("Invalid email");try{d.insert(ev,r,n.trim(),m);}catch(SQLIntegrityConstraintViolationException e){throw new IllegalArgumentException("Already registered for this event");}}}
Dao dao=new Dao();Service service=new Service(dao);JComboBox<String>event=new JComboBox<>(),filter=new JComboBox<>(new String[]{"All"});JTextField reg=new JTextField(12),name=new JTextField(14),email=new JTextField(18);JLabel status=new JLabel("Ready");DefaultTableModel model=new DefaultTableModel(new String[]{"Register No","Name","Email"},0);int page=0;
EventRegistrationApp(){super("Campus Event Registration");JTabbedPane tabs=new JTabbedPane();JPanel form=new JPanel(new GridLayout(0,2,5,5));form.add(new JLabel("Event"));form.add(event);form.add(new JLabel("Register no"));form.add(reg);form.add(new JLabel("Name"));form.add(name);form.add(new JLabel("Email"));form.add(email);JButton save=new JButton("Register");form.add(save);form.add(status);tabs.add("Register",form);JPanel list=new JPanel(new BorderLayout());list.add(filter,BorderLayout.NORTH);list.add(new JScrollPane(new JTable(model)));JPanel nav=new JPanel();JButton prev=new JButton("Prev"),next=new JButton("Next");nav.add(prev);nav.add(next);list.add(nav,BorderLayout.SOUTH);tabs.add("Registrations",list);add(tabs);save.addActionListener(e->save());prev.addActionListener(e->{page=Math.max(0,page-1);load();});next.addActionListener(e->{page++;load();});filter.addActionListener(e->{page=0;load();});loadEvents();setSize(760,420);setDefaultCloseOperation(EXIT_ON_CLOSE);setLocationRelativeTo(null);}
void loadEvents(){new SwingWorker<List<String>,Void>(){protected List<String>doInBackground()throws Exception{return dao.events();}protected void done(){try{for(String s:get()){event.addItem(s);filter.addItem(s);}}catch(Exception e){status.setText("DB error: "+e.getMessage());}}}.execute();}
void save(){String ev=(String)event.getSelectedItem(),r=reg.getText(),n=name.getText(),m=email.getText();new SwingWorker<Void,Void>(){protected Void doInBackground()throws Exception{service.register(ev,r,n,m);return null;}protected void done(){try{get();status.setText("Registration accepted");load();}catch(Exception e){status.setText("Rejected: "+e.getCause().getMessage());}}}.execute();}
void load(){String f=(String)filter.getSelectedItem();new SwingWorker<List<String[]>,Void>(){protected List<String[]>doInBackground()throws Exception{return dao.page(f==null?"All":f,page*25);}protected void done(){try{model.setRowCount(0);for(String[]r:get())model.addRow(r);status.setText("Page "+(page+1));}catch(Exception e){status.setText("Load failed: "+e.getMessage());}}}.execute();}
public static void main(String[]a){SwingUtilities.invokeLater(()->new EventRegistrationApp().setVisible(true));}}
